\filldraw[fill=white,thick] (8,0) circle (0.11);
\node[anchor=south] at (8,0.22) {new value};
\draw[->] (3,-0.9) -- (3,-0.12);
\node[below] at (3,-0.95) {$\bar{x}$};
\end{tikzpicture}
